import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 2000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(599);
    });

    it("returns 0 for empty cart even with freeOver configured", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([], 100)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 900 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 3 },
      ];
      expect(calc.computeShippingCents(lines, 300)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 250, 1)], 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // weight = 500 → first bracket (upToGrams: 500 is inclusive)
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(300);
    });

    it("selects next bracket when weight exceeds previous boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // weight = 501 → second bracket
      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 1000)).toBe(500);
    });

    it("selects highest bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 1000)).toBe(900);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 1500);
      expect(calc.computeShippingCents([makeLine("a", 5001, 1)], 1000)).toBe(1500);
    });

    it("falls back to highest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 10000, 1)], 1000)).toBe(900);
    });

    it("sums weights across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200*2 + 150*1 = 550 → second bracket
      const lines = [makeLine("a", 200, 2), makeLine("b", 150, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(500);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 900 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      expect(calc.computeShippingCents([makeLine("a", 250, 1)], 1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("has correct shape and properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("supports undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const lines: CartLine[] = [
    { product: { id: "p1", name: "Product 1", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "p2", name: "Product 2", unitPriceCents: 200 }, quantity: 1 },
  ];

  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };
    const refreshed = await refreshPrices(lines, fetcher);
    expect(refreshed[0].product.unitPriceCents).toBe(150);
    expect(refreshed[1].product.unitPriceCents).toBe(250);
    expect(refreshed[0].quantity).toBe(2);
    expect(refreshed[1].quantity).toBe(1);
  });

  it("preserves other product fields", async () => {
    const lineWithWeight: CartLine[] = [
      { product: { id: "p1", name: "Heavy", unitPriceCents: 100, weightGrams: 500 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const refreshed = await refreshPrices(lineWithWeight, fetcher);
    expect(refreshed[0].product.weightGrams).toBe(500);
    expect(refreshed[0].product.name).toBe("Heavy");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("service down");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("calls fetcher with correct product ids", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(100),
    };
    await refreshPrices(lines, fetcher);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p2");
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities for the same product", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("handles different products independently", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);
      expect(cart.itemCount).toBe(3);
    });

    it("rejects zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
      expect(() => cart.add(bad, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates the quantity of an existing product", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 1)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("a");
      expect(snap[0].quantity).toBe(2);
    });

    it("mutations to snapshot do not affect cart", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPrice * quantity", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2000
      cart.add(productB, 1); // 2000
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(4000);
    });

    it("applies discount from injected policy", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(productA, 2); // subtotal = 2000
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(2000);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: () => 99999,
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(productA, 1); // subtotal = 1000
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(productA, 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(150),
      };
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        region: "US-CA",
      });
      cart.add(productA, 1); // subtotal = 1000, discount = 200, discounted = 800
      cart.totals();
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    });

    it("computes shipping on discounted subtotal and lines", () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(599),
      };
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: () => 300,
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        shippingCalculator: mockShipping,
      });
      cart.add(productA, 1); // subtotal = 1000, discount = 300, discounted = 700
      cart.totals();
      expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        700,
      );
    });

    it("computes totalCents = discountedSubtotal + tax + shipping", () => {
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 200 },
        taxCalculator: { computeTaxCents: () => 80 },
        shippingCalculator: { computeShippingCents: () => 500 },
      });
      cart.add(productA, 1); // subtotal=1000, discount=200, discounted=800
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(200);
      expect(totals.taxCents).toBe(80);
      expect(totals.shippingCents).toBe(500);
      expect(totals.totalCents).toBe(800 + 80 + 500);
    });

    it("returns all zeros for empty cart", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("clamps negative tax to 0", () => {
      const cart = new Cart({
        taxCalculator: { computeTaxCents: () => -50 },
      });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const cart = new Cart({
        shippingCalculator: { computeShippingCents: () => -100 },
      });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("defaults region to US", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(productA, 1);
      cart.totals();
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("updates prices from priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
      expect(result.lines[0].product.unitPriceCents).toBe(1500);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
    });

    it("skips price refresh when no priceFetcher provided", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout({});
      expect(result.totals.subtotalCents).toBe(1000);
    });
  });

  describe("inventory check", () => {
    it("passes when inventory is available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "out of stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(5);
        expect(ie.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(3);
      }
    });

    it("checks all items; first denial wins", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("b");
      }
    });

    it("skips inventory check when no inventoryChecker provided", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout({});
      expect(result.totals.subtotalCents).toBe(1000);
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax calculation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(productA, 1); // subtotal 1000, no discount → taxable 1000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(100); // floor(1000 * 0.1)
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "FR",
      });
      cart.add(productA, 1); // subtotal=1000, discount=200, discounted=800

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // tax = floor(800 * 0.2) = 160
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(160);
    });

    it("propagates async tax provider rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service timeout")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service timeout",
      );
    });

    it("uses sync tax calculator when no asyncTaxProvider", async () => {
      const cart = new Cart({
        taxCalculator: { computeTaxCents: () => 75 },
      });
      cart.add(productA, 1);
      const result = await cart.checkout({});
      expect(result.totals.taxCents).toBe(75);
    });
  });

  describe("full pipeline composition", () => {
